    <script src="js/main.js"></script><script>
        const formatPrice = value => `${value.toLocaleString('vi-VN')} đ`;
        const updateCart = () => { let subtotal = 0; document.querySelectorAll('.cart-item').forEach(item => { const quantity = Number(item.querySelector('output').textContent); subtotal += Number(item.dataset.price) * quantity; }); document.getElementById('subtotal').textContent = formatPrice(subtotal); document.getElementById('grandTotal').textContent = formatPrice(subtotal); };
        document.querySelectorAll('.cart-item').forEach(item => item.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', () => { const output = item.querySelector('output'); const step = button.dataset.action === 'increase' ? 1 : -1; output.textContent = Math.max(1, Math.min(9, Number(output.textContent) + step)); updateCart(); })));
        document.querySelectorAll('.remove-item').forEach(button => button.addEventListener('click', () => { button.closest('.cart-item').remove(); updateCart(); }));
        document.getElementById('couponForm').addEventListener('submit', event => { event.preventDefault(); alert(document.getElementById('couponCode').value.trim().toUpperCase() === 'ETECH10' ? 'Đã áp dụng mã giảm giá 10%.' : 'Mã giảm giá không hợp lệ.'); });
    </script>
